#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (1) ---
patchFile('siman_027/mechaber/part-001.txt', 'mechaber', {
  '1#main': `Not to cut a limb from the animal while it is still convulsing. In it is one seif. One who cuts from an animal after it was slaughtered properly and is still convulsing — it is forbidden to eat from it until the animal dies.`,
});

// --- siftei-kohen (2) ---
patchFile('siman_027/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `[<b>Forbidden to eat, etc.</b> Because it is written: you shall not eat upon the blood; and Chazal expounded it is forbidden to eat from an animal before its soul departs; but after it died, it is permitted to eat from it even what was cut from it before it died.]`,
  '1#ב': `[<b>Until the animal dies.</b> But after it died, it is permitted to eat it and feed it to a non-Jew — end; Tur; and this refers to the first clause: slaughtered properly; but where it was not slaughtered properly — it is obvious: since forbidden to Israel because of eiver min hachai, since he cut from it before its soul departed — also for a non-Jew forbidden, for a son of Noah is commanded regarding eiver min hachai. And likewise where he cut from a tamei animal while still convulsing, even though he slaughtered it properly — forbidden to give to sons of Noah, for shechitah does not apply to a tamei animal. And so Rashba in Tur HaDeshen, the long one, daf 30, end 2b; and thus: and to invite a non-Jew for intestines, or for flesh separating from the animal before its soul departs — if a tahor animal, which is subject to shechitah, and was slaughtered by Israel, who is subject to shechitah — permitted; but in a tamei animal, even by Israel; and if also in a tahor animal by a non-Jew — flesh separating from it before its soul departs — forbidden to invite the non-Jew for it, and even after the animal's soul departs. And although Rambam, may his memory be blessed, ruled in Sefer Shoftim (in a tahor animal too) for Israel permitted and for a non-Jew forbidden — I do not know the reason for his words, etc. — end; and so Kesef Mishneh, chapter 9 of Hilchot Shoftim; and so in the Talmud and Rashi, chapter HaOr VeHaRotav (Chullin daf 121b). And Maharshal wrote, chapter HaShochet, end siman 17: in an animal of a non-Jew, even if Israel slaughtered it — nevertheless, since he was not commanded regarding shechitah — in his animal shechitah did not permit it for him, and its law is as if a non-Jew slaughtered it; and with this Rama's words are settled, and Semag — see there; and see above siman 62, s.k. 3.]`,
});

// --- turei-zahav (1) — long responsum ---
patchFile('siman_027/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Until the animal dies.</b> For it is written: you shall not eat upon the blood — implying before its soul departs; and Tur concluded: but after it died, permitted to eat it and feed it to a non-Jew; and permitted to feed intestines to a non-Jew. Explanation: we would have said that for a non-Jew shechitah does not permit except death specifically, and this flesh was cut before it died — its death afterward would not avail him, for it was cut before its permissibility; but since for Israel shechitah avails and what was cut while convulsing is permitted, provided he waited until it died — there is nothing permitted for Israel and forbidden for a non-Jew. And likewise regarding intestines Tur wrote it is permitted to invite a non-Jew for them, and we do not say: since he slaughtered the simanim, it is as if he removed them and placed them in a basket. In Tur it is written here: the spinal column broke and majority of flesh with it — neveilah; and Beit Yosef wondered why Tur needed to write laws of neveilah, for his way is not to write except laws of prohibition and permission. And my brother Mahar R' Yehudah Halevi, may his memory be blessed, answered: there is a practical difference regarding doubt of egg of treifah, as Tur wrote siman 86: in egg of treifah we follow its doubt stringently — responsum from my brother the gaon Rabbi Yitzchak Halevi, may his memory be blessed, to one of the scholars: <br><b>I saw</b> the work of your fingers, which you established — work of sharpness in pilpul and expertise united. Regarding a bird's spinal column that broke and the fragments returned and connected and became one. And the cord within it and the flesh upon it are whole, established and standing. And although I do not stand with you in the body of the law — nevertheless, pleasant words are upon me. What you wrote to declare treifah because perhaps majority of flesh broke with it and returned and healed, as the fragments returned together, and it is like a scab that rose from a wound, etc. — end: <br><b>I wonder</b>: for certainly, if majority of flesh broke with the spinal column, it could not live, as Ze'eira said: the spinal column broke and majority of flesh with it — neveilah and imparts impurity, etc.; and if it had possibility to live, it would not be neveilah but mere treifah. And how is neveilah possible — dead — that its fragments return together and the flesh heals and it lives afterward? And further: we say regarding a broken leg where one makes it treifah — kosher if skin and flesh cover the majority; and even if there is no basis to establish it does not go outside, such as if it returned and connected — Rabbenu Tam ruled kosher; and so Ra'osh and Tur; and so we hold; and we are not concerned lest the skin and flesh too tore and did not cover the majority, and they healed closely as the fragments returned and connected. And further: it is not true that in every matter where there is a scab that rose from a wound — a scab is only specifically where Chazal said treifah because of perforation. And I wrote clear proofs for this in another responsum; there is no need to extend here: <br><b>And what</b> the rabbi brought as proof to declare treifah even without majority of flesh with it, from Rav Chisda: we too taught: melikah with a knife imparts impurity to garments at the house of slaughter — and if you say treifah, its melikah is its shechitah — let the knife avail to purify it from neveilah; and you wrote: from that he said "and if you say treifah" and did not say "and if you say not neveilah," etc. — who mentions treifah? It implies the law is so everywhere: what should be neveilah is neveilah, and what is not neveilah is treifah in any case — end; I say: initially nothing is difficult, for this obvious matter — Rav Chisda could not say "and if you say not neveilah and not treifah" in breaking spinal column and majority of flesh — for then certainly it would not impart impurity to garments at cutting the simanim afterward, since it is valid shechitah to purify from neveilah for Rav Chisda, who did not know the answer there; and he should not have said at all "and if you say," etc., that from our teaching it imparts to garments it is proven clearly it is neveilah — rather certainly because we can say in breaking spinal column and majority of flesh it was treifah, and therefore when he completes and cuts the simanim it becomes neveilah and imparts to garments; and as we taught the principle: R' Yeshbab said in the name of R' Yehoshua: whatever was invalidated in its shechitah is neveilah, etc.; and R' Akiva conceded to him. If so, there is no support from that baraita for Ze'eira. Therefore Rav Chisda said this is not so — for then the knife at cutting the simanim should avail to purify from neveilah, since in slaughtering the simanim there is no disqualification, and cutting the flesh and spinal column is not in the matter of shechitah but like other treifot that occurred before shechitah. And that which we taught: one who slaughters from the nape — his shechitah is invalid — is to say it is treifah and not neveilah, as Rashi explained — see there. And further: according to you it is still not resolved — your precision: why did Rav Chisda need to mention treifah? When Rav Chisda came here, was it to teach us the law that whatever is not neveilah is nevertheless treifah? He came only to refute that it was neveilah, and he should have said "and if you say it is not neveilah," etc.; and it is clear as I explained. And what the rabbi wrote in the name of Tosafot, first chapter of Eruvin (daf 7), in the passage beginning "such as spinal column," etc.: the spinal column was severed — treifah even without severing the cord — for even below the nostrils, where there is no treifah in severing the cord, it deals; and this is not like Rashi at the beginning of Elu Treifot, that the spinal column is not treifah except with severing the cord — end; your words are torn apart. And from this there was some proof that also in a broken spinal column it is treifah without majority of flesh and without severing the cord. But in truth it does not appear and is not heard from these Tosafot to declare treifah in a broken spinal column — except when two vertebrae are missing according to Beit Shammai and one vertebra according to Beit Hillel; in such a great deficiency from the spinal column it is certainly treifah; and from this the baraita challenges at the beginning of Elu Treifot — the tanna of the house of R' Yishmael, to count also this deficiency in the spinal column. But if the spinal column broke without missing a vertebra — it is not treifah unless the cord was severed, as Rashi explained there; and that is what is counted in the mishnah of Elu Treifot. And Tosafot do not dispute at all on Rashi; and so is proven in the Gemara sugya that discusses a case where the spinal column broke. And so Rif, Ra'osh, Tur, and all poskim agreed to this; and the rabbi, according to his sharpness, did not analyze this. And if so, we have no proof to declare treifah in a broken spinal column without majority of flesh with it when the cord is whole — it is obvious that where the cord is severed, anywhere from the brain until the nostrils, it is certainly treifah; and in vain the rabbi toiled and strained in pilpul — there is no need for severing the cord for breaking the spinal column, for treifah of the cord is an entirely different treifah by itself, from the brain until the opening of the nostrils; and breaking the spinal column with majority of flesh is another treifah by itself. However, in breaking the spinal column alone, with cord and flesh whole — and all the more when the fragments returned and connected — we found nowhere that it is treifah. And no posek of all famous poskim omitted to mention this treifah; and in Shulchan Aruch he did not mention at all breaking the spinal column — because he follows Beit Yosef's reasoning: Beit Yosef wondered on Tur mentioning broken spinal column and majority of flesh with it — neveilah. And in truth Tur came to inform us here: all the more it is treifah; and Tur did not write thus, for it would imply from this it is treifah and not neveilah and does not impart impurity — this is against the Gemara's conclusion; therefore Tur brought Ze'eira's words literally — and simple. And Shulchan Aruch did not write this because it is an obvious matter that it is treifah — for even neveilah it is and imparts. And if you say: if it is treifah even without majority of flesh with it, Shulchan Aruch should have written at least this law, not omit the entire matter. And further: Rambam toiled and listed all treifot that can be found and wrote they are in intentional count of seventy — see there, chapter 3 of Hilchot Shechitah — and did not mention at all this treifah of broken spinal column without majority of flesh. And that he did not count there breaking with majority of flesh — because it is neveilah, and Rambam already counted it among the six neveilot; and it is in chapter 3 of Hilchot Shechitah; and we cannot add to the treifot Chazal counted: <br><b>And clear proof</b> for our words: why does the baraita at the beginning of Elu Treifot not challenge the baraita of the tanna of the house of R' Yishmael — why does it not also count this treifah of broken spinal column without majority of flesh? And also according to the conclusion there it is certainly resolved only that it is not treifah at all unless majority of flesh is with it — then it is even neveilah to impart, as Ze'eira said. And what the rabbi wrote: R' Yishmael's words are singular — I do not know which tanna disputes him in this, since it is proven clearly from this baraita that this is not treifah at all; whence does he say our tanna disputes and includes it in this principle? And it is simple from several places: whatever we can minimize dispute and say all agree — we say thus; and all the more in our case, where we found no disputant on this baraita in this; and further: if it were treifah without majority of flesh, Ze'eira should more have informed us this law explicitly than informing us it is neveilah with majority of flesh. And at least he should have informed us this law too, that even without majority of flesh it is treifah. Granted, in that which R' Eliezer said there: the thigh was removed and its cavity — neveilah — it is not difficult why R' Eliezer did not say: without the entire cavity removed, only some of the inner flesh — treifah, as Rashi explained there, for that is taught explicitly in the mishnah, as I brought there — Rashi, may his memory be blessed: an animal whose legs were cut, etc.; and R' Eliezer did not need to say; and if you say: if so, R' Eliezer informs us nothing regarding treifot, since from the mishnah we hear that even with some removed it is treifah? Rather he informs us: with the entire removed — it is neveilah for it. And if the halakhah came for the Messiah — to inform us: granted R' Shmuel bar Nachmani, who said: torn like a fish — neveilah; and Chizkiya, who said: on a board — neveilah — he informs us too that all the more it is treifah. But R' Eliezer is difficult. This is no difficulty: for we say explicitly in chapter 4 of Zevachim there is no challenge thus except where the halakhah was decided for practice; and this applies only to something practiced in our time; but when not intending practice but to study and teach the law — they are for the Messiah — we need to teach like the entire order of Kodashim, Zeraim, and Taharot, where we say: interpret and receive reward. And what R' Eliezer said is law of neveilah in tractate Chullin, and it belongs to laws of impurity and purity — that is because R' Eliezer's entire subject is to say shechitah afterward does not avail to purify from neveilah; if so, it applies well to laws of shechitah. And there is also practical difference in laws of shechitah: if its shechitah is called shechitah — forbidden to slaughter its son or mother that day, which is not so if its shechititah is not shechitah, as stated in chapter Oto VeEt Beno. And further: in treifah, if there is doubt in an egg whether from this treifah or from a slaughtered one — forbidden; in neveilah, if doubt whether from this neveilah or from a slaughtered one — permitted, as written in Sefer HaTerumot; and Tur brings it in Yoreh Deah siman 86; and the reason: egg of neveilah is rabbinic and egg of treifah is d'oraisa — see there in Beit Yosef; and what appears correct in my humble opinion — I wrote — Yitzchak Halevi. End of responsum: <br><b>Well</b> did my aforementioned brother gaon aim at the halakhah that there is no treifah at all in a broken spinal column when the cord is intact; and there is proof from an arranged Gemara, chapter HaShochet (Chullin daf 28): we grant that if its spinal column and spinal column break — it is treifah; and this "spinal column" means the spinal cord, as Rashi explained explicitly in Zevachim (daf 65); and if one thinks that in breaking the spinal column without the cord there is also treifah — the Talmud would list two types of treifah, for from severing the cord alone it is obvious there is treifah without breaking the spinal column; if so, why would the questioner need to list two types of treifah? It should have said only: granted, in breaking the spinal column — treifah; and since the law of melikah comes to inform us in this — rather necessarily in breaking the spinal column there is no treifah except because of the cord alone — treifah; and the questioner listed breaking the spinal column because the essence of melikah is at the spinal column, lest you err that in the spinal column alone is the law of melikah — if so, there is no treifah here; therefore he also listed the spinal column, since it too is included in the spinal column for melikah; if so, there is treifah from the aspect of the cord: <br><b>And greater</b> than this it appears to me to be lenient: even in broken spinal column and majority of flesh with it when the cord is intact — kosher; for Tosafot wrote in chapter HaShochet (Chullin daf 32), s.v. velichashov, etc.: and if you say, let it also count Ze'eira, who said: the spinal column broke and majority of flesh with it — neveilah; and one may say: it is not neveilah unless the spinal cord too was severed — and it taught there that the spinal cord alone was severed — forbidden; end — behold it is proven that even treifah is not without the cord; for otherwise Tosafot's question would not be resolved; and why would it not count severing the spinal column without the cord as treifah — behold it also counts treifot there? Rather necessarily there is no treifah here at all without the cord; and Tosafot listed neveilah since Ze'eira deals with neveilah. And although from my brother's words it appears that in broken spinal column with majority of flesh it is treifah without the cord — it appears to me, as I wrote, and what Tur wrote: broken spinal column and majority of flesh — neveilah — that is when the cord was severed; and it teaches that for neveilah it is specifically with majority of flesh.`,
});

// --- baer-heitev (2) ---
patchFile('siman_027/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `<b>From it.</b> See Shach.`,
  '1#ב': `<b>The animal.</b> And Taz wrote: but after it died, permitted to eat from it even what was cut before it died; and permitted to feed it to a non-Jew — even though for a non-Jew shechitah does not permit except death, and this flesh was cut before it died — one might have thought death afterward would not avail him, since it was cut before its permissibility; it teaches there is nothing permitted for Israel and forbidden for a non-Jew. And Shach wrote: but if he cut from a tamei animal before its soul departed — since shechitah does not apply to it — forbidden to give from it to sons of Noah. And Maharshal wrote: in an animal of a non-Jew, even if Israel slaughtered it — since he was not commanded regarding shechitah — in his animal shechitah did not permit it for him; its law is as if a non-Jew slaughtered it; and if he cut from it while convulsing — forbidden to give to sons of Noah. And Taz wrote: in Tur it is written here: the spinal column broke and majority of flesh with it — neveilah; and for us too there is practical difference regarding doubt of egg of treifah, as written siman 86: in egg of treifah we follow doubt stringently — see there; and he wrote on this in Taz: it appears to me to be lenient even in broken spinal column and majority of flesh with it when the cord is intact — kosher; and what Tur wrote: broken spinal column and majority of flesh — neveilah — that is specifically when the cord was severed — see there at length. And so Peri Chadash: everything depends on the cord. And in Beit Yosef, siman 162, he tends to be stringent even without majority of flesh. And in She'eilot Ya'avetz, she'eilah 3, he also refutes Taz's proof from Tosafot, Chullin daf 32, s.v. velichashov — see there; also proven from mishnah of VeElu Kesherot, etc., that lists broken spinal column and the cord was not severed, and does not teach broken spinal column and majority of flesh — rather certainly in such a case treifah even if the cord was not severed — see there. And Tur wrote: also for intestines it is permitted to invite a non-Jew, and we do not say: since he slaughtered the simanim, it is as if he removed the intestines and placed them in a basket like water — it teaches: no.`,
});

